// GoldenBoot: AdGuard filter engine for Cobalt. Plain C++ (no Chromium types),
// so it can also be built and tested on its own. Rules come from
// adguard_rules.inc, generated by patches/adguard_rules.py.

#ifndef COBALT_NETWORK_ADGUARD_ENGINE_H_
#define COBALT_NETWORK_ADGUARD_ENGINE_H_

#include <stddef.h>
#include <stdint.h>

#include <string>

namespace cobalt {
namespace network {
namespace adguard {

// Content types (same bits as TYPES in adguard_rules.py).
enum ContentType : uint32_t {
  kTypeScript = 1,
  kTypeImage = 2,
  kTypeStylesheet = 4,
  kTypeXhr = 8,
  kTypeMedia = 16,
  kTypeFont = 32,
  kTypeSubdocument = 64,
  kTypeWebsocket = 128,
  kTypeOther = 256,
  kTypeObject = 512,
  kTypePing = 1024,
};

// Page-level exceptions (same bits as PAGE in adguard_rules.py).
enum PageFlag : uint32_t {
  kPageDocument = 1,
  kPageElemhide = 2,
  kPageGenerichide = 4,
  kPageSpecifichide = 8,
  kPageJsinject = 16,
  kPageUrlblock = 32,
  kPageContent = 64,
};

struct Request {
  std::string url;             // the requested URL
  std::string host;            // its host, lower case
  std::string page_host;       // host of the page making the request ("" = unknown)
  size_t page_registry_len = 0;  // length of page_host's public suffix
  bool third_party = false;
  uint32_t type = 0;           // one ContentType bit; 0 = unknown
  bool domain_lists_only = false;  // skip pattern rules
};

// True if the request is blocked. |page_flags| comes from EnginePageFlags().
// |why| (optional) gets the matching rule.
bool EngineShouldBlock(const Request& r, uint32_t page_flags, std::string* why);

// Page-level exception flags ($document, $elemhide, ...) for a page URL.
uint32_t EnginePageFlags(const std::string& page_url, const std::string& page_host,
                         size_t registry_len);

// Test switches (Android property debug.gb.adguard, read by adguard_filter.cc).
enum Mode : uint32_t {
  kModeNoGenericCosmetic = 1,  // no generic element hiding
  kModeNoPageScript = 2,       // no cosmetic rules or scriptlets at all
  kModeNoNetwork = 4,          // no request blocking
  kModeGenericAsCss = 8,       // all generic hiding as one style sheet (old way)
  // YouTube TV player answers (kYtTv in the page script; default: ad lists set to []):
  kModeYtDeleteKeys = 16,      // delete the ad keys instead (breaks playback)
  kModeYtReserialize = 32,     // re-serialise the answer unchanged
  kModeYtOff = 64,             // handler off (ads play)
  kModeYtOriginalText = 128,   // original text in a new Response
  kModeAdProbes = 256,         // RAW/FINAL answer reports, env check, verbose scriptlets
  kModeTraceYt = 512,          // log every youtube.com /youtubei/ request (network level) and
                               // every fetch/XHR/Worker the page starts (page script)
};

// JavaScript that applies this page's cosmetic rules and scriptlets, or "" if
// there is nothing to apply.
std::string EnginePageScript(const std::string& host, size_t registry_len,
                             uint32_t page_flags, uint32_t mode);

// One-line description of the compiled lists, for the log.
std::string EngineInfo();

}  // namespace adguard
}  // namespace network
}  // namespace cobalt

#endif  // COBALT_NETWORK_ADGUARD_ENGINE_H_
